{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or slightly positive (≥0.00) and historical prices show downward momentum.",
    "Reduce forecast overshoots following sharp price spikes by applying a 10-15% dampening factor to the immediate next period.",
    "Apply mean reversion bias: if forecast deviates >±5% from recent 7-day average, adjust toward that average with a decay factor of 0.8 per period.",
    "Increase downward bias when sentiment is negative (≤ -0.25) and historical prices are trending downward.",
    "Avoid over-optimism in short-term (1-3 day) forecasts when sentiment is weak; use 30-day moving average as a floor for price stability."
  ]
}
